(1,'f6a6a5481b875fd2','SELECT  COUNT(DISTINCT(uid)) FROM wpta_burst_statistics AS statistics  WHERE statistics.time BETWEEN 1773002685 AND 1773006885  AND ( (time + time_on_page / 1000 + 60 + 240) > 1773003285)    ',0.003046,0.003046,0.003046,1773003285,1),
(2,'275bd5cf94d4fef0','SELECT COUNT(DISTINCT statistics.uid) as visitors, COUNT( statistics.ID ) as pageviews, AVG( statistics.time_on_page ) as avg_time_on_page FROM wpta_burst_statistics AS statistics  WHERE statistics.time BETWEEN 1772323200 AND 1772927999     ',0.00048,0.001097,0.000295,1773003424,9),
(3,'e632cfbf9988a31a','SELECT statistics.page_url as page_url, COUNT( statistics.ID ) as pageviews FROM wpta_burst_statistics AS statistics  WHERE statistics.time BETWEEN 1772323200 AND 1772927999  GROUP BY page_url  ORDER BY pageviews DESC LIMIT 1',0.000328,0.000821,0.000239,1773003424,9),
(4,'e0bda0c8a391f703','SELECT sessions.referrer as referrer, COUNT( statistics.ID ) as pageviews FROM  (\n                            SELECT \n                                s.ID,\n                                s.page_url,\n                                s.page_id,\n                                s.page_type,\n                                s.time,\n                                s.uid,\n                                s.time_on_page,\n                                s.parameters,\n                                s.fragment,\n                                s.browser_id,\n                                s.browser_version_id,\n                                s.platform_id,\n                                s.device_id,\n                                s.session_id,\n                                s.first_time_visit,\n                                s.bounce,\n                                sess.referrer\n                            FROM wpta_burst_statistics AS s\n                            JOIN wpta_burst_sessions AS sess ON s.session_id = sess.ID\n                            WHERE s.time BETWEEN 1772323200 AND 1772927999\n                                AND sess.referrer != \'\' AND sess.referrer IS NOT NULL \n                        ) AS statistics   INNER JOIN wpta_burst_sessions AS sessions ON statistics.session_id = sessions.ID WHERE statistics.time BETWEEN 1772323200 AND 1772927999  GROUP BY referrer  ORDER BY pageviews DESC LIMIT 1',0.000538,0.000717,0.000421,1773003424,9),
