INSERT INTO `wpta_latepoint_processes` VALUES
(1,'New Booking Notification','booking_created','[{\"type\":\"group\",\"trigger_condition\":false,\"items\":[{\"type\":\"action\",\"id\":\"pa_D66Nzd\",\"settings\":{\"status\":\"active\",\"type\":\"send_email\",\"settings\":{\"to_email\":\"{{agent_full_name}} <{{agent_email}}>\",\"subject\":\"New Appointment Received\",\"content\":\"<div style=\\\"padding: 20px; background-color: #f0f0f0; font-family: -apple-system, system-ui, BlinkMacSystemFont, \\\"Segoe UI\\\", Roboto, \\\"Helvetica Neue\\\", Arial, sans-serif;\\\">\\n\\t<div style=\\\"background-color: #fff; padding: 30px; margin: 0px auto; max-width: 450px; box-shadow: 0px 2px 6px -1px rgba(0,0,0,0.2); border-radius: 6px;\\\">\\n\\t\\t<div style=\\\"margin: 0px auto 30px auto; border-bottom: 1px solid #eee; padding-bottom: 20px;\\\">\\n\\t\\t\\t<table style=\\\"width: 100%;\\\">\\n\\t\\t\\t\\t<tr>\\n\\t\\t\\t\\t\\t<td>{{business_logo_image}}<\\/td>\\n\\t\\t\\t\\t\\t<td style=\\\"text-align: right;\\\"><span style=\\\"color: #7b7b7b;\\\">Questions?<\\/span><br\\/><strong>{{business_phone}}<\\/strong><\\/td>\\n\\t\\t\\t\\t<\\/tr>\\n\\t\\t\\t<\\/table>\\n\\t\\t<\\/div>\\n\\t\\t<div style=\\\"font-size: 16px; line-height: 1.5;\\\">\\n\\t\\t\\t<div style=\\\"font-size: 16px; margin-bottom: 20px; line-height: 1.6;\\\">\\n\\tHi {{agent_full_name}},\\n\\t<br\\/><br\\/>\\n\\tYou have received a new appointment request from {{customer_full_name}}\\n<\\/div>\\n<h4 style=\\\"margin-bottom: 10px; margin-top: 0px; font-size: 16px; font-weight: bold;\\\">Customer Information<\\/h4>\\n<ul>\\n\\t<li>\\n\\t\\t<span>Full Name:<\\/span> <strong>{{customer_full_name}}<\\/strong>\\n\\t<\\/li>\\n\\t<li>\\n\\t\\t<span>Email Address:<\\/span> <strong>{{customer_email}}<\\/strong>\\n\\t<\\/li>\\n\\t<li>\\n\\t\\t<span>Phone:<\\/span> <strong>{{customer_phone}}<\\/strong>\\n\\t<\\/li>\\n\\t<li>\\n\\t\\t<span>Comments:<\\/span> <strong>{{customer_notes}}<\\/strong>\\n\\t<\\/li>\\n<\\/ul>\\n<h4 style=\\\"margin-bottom: 10px; margin-top: 0px; font-size: 16px; font-weight: bold;\\\">Appointment Information<\\/h4>\\n<ul>\\n\\t<li>\\n\\t\\t<span>Service:<\\/span> <strong>{{service_name}}<\\/strong>\\n\\t<\\/li>\\n\\t<li>\\n\\t\\t<span>Date, Time:<\\/span> <strong>{{start_date}}, {{start_time}} - {{end_time}}<\\/strong>\\n\\t<\\/li>\\n<\\/ul>\\n<h4 style=\\\"margin-bottom: 10px; margin-top: 0px; font-size: 16px; font-weight: bold;\\\">Order Summary<\\/h4>\\n<div style=\\\"margin-bottom: 20px;\\\">{{order_summary_breakdown}}<\\/div>\\n<div style=\\\"margin-top: 25px;\\\">\\n\\t<a href=\\\"{{manage_booking_url_agent}}\\\" style=\\\"display: block; text-decoration: none; padding: 10px; border-radius: 6px; text-align: center; font-size: 18px; color: #fff; background-color: #1e7bff; font-weight: 700;\\\">Manage This Appointment<\\/a>\\n<\\/div>\\n\\t\\t<\\/div>\\n\\t<\\/div>\\n\\t<div style=\\\"max-width: 450px; margin: 10px auto; text-align: center;\\\">{{business_address}}<\\/div>\\n<\\/div>\"}}},{\"type\":\"action\",\"id\":\"pa_s0wms3\",\"settings\":{\"status\":\"active\",\"type\":\"send_email\",\"settings\":{\"to_email\":\"{{customer_full_name}} <{{customer_email}}>\",\"subject\":\"Appointment Confirmation\",\"content\":\"<div style=\\\"padding: 20px; background-color: #f0f0f0; font-family: -apple-system, system-ui, BlinkMacSystemFont, \\\"Segoe UI\\\", Roboto, \\\"Helvetica Neue\\\", Arial, sans-serif;\\\">\\n\\t<div style=\\\"background-color: #fff; padding: 30px; margin: 0px auto; max-width: 450px; box-shadow: 0px 2px 6px -1px rgba(0,0,0,0.2); border-radius: 6px;\\\">\\n\\t\\t<div style=\\\"margin: 0px auto 30px auto; border-bottom: 1px solid #eee; padding-bottom: 20px;\\\">\\n\\t\\t\\t<table style=\\\"width: 100%;\\\">\\n\\t\\t\\t\\t<tr>\\n\\t\\t\\t\\t\\t<td>{{business_logo_image}}<\\/td>\\n\\t\\t\\t\\t\\t<td style=\\\"text-align: right;\\\"><span style=\\\"color: #7b7b7b;\\\">Questions?<\\/span><br\\/><strong>{{business_phone}}<\\/strong><\\/td>\\n\\t\\t\\t\\t<\\/tr>\\n\\t\\t\\t<\\/table>\\n\\t\\t<\\/div>\\n\\t\\t<div style=\\\"font-size: 16px; line-height: 1.5;\\\">\\n\\t\\t\\t<div style=\\\"font-size: 16px; margin-bottom: 20px; line-height: 1.6;\\\">\\n\\tHi {{customer_full_name}},\\n\\t<br>\\n\\t<br>\\n\\tYour {{service_name}} appointment with <strong>{{agent_full_name}}<\\/strong> is <strong>{{booking_status}}<\\/strong>.\\n<\\/div>\\n<h4 style=\\\"margin-bottom: 10px; margin-top: 0px; font-size: 16px; font-weight: bold;\\\">Appointment Details:<\\/h4>\\n<ul>\\n\\t<li>\\n\\t\\t<span>Agent:<\\/span> <strong>{{agent_full_name}}<\\/strong>\\n\\t<\\/li>\\n\\t<li>\\n\\t\\t<span>Service:<\\/span> <strong>{{service_name}}<\\/strong>\\n\\t<\\/li>\\n\\t<li>\\n\\t\\t<span>Date, Time:<\\/span> <strong>{{start_date}}, {{start_time}} - {{end_time}}<\\/strong>\\n\\t<\\/li>\\n<\\/ul>\\n<h4 style=\\\"margin-bottom: 10px; margin-top: 0px; font-size: 16px; font-weight: bold;\\\">Order Summary<\\/h4>\\n<div style=\\\"margin-bottom: 20px;\\\">{{order_summary_breakdown}}<\\/div>\\n<div style=\\\"margin-top: 25px;\\\">\\n\\t<a href=\\\"{{manage_booking_url_customer}}\\\" style=\\\"display: block; text-decoration: none; padding: 10px; border-radius: 6px; text-align: center; font-size: 18px; color: #fff; background-color: #1e7bff; font-weight: 700;\\\">Manage This Appointment<\\/a>\\n<\\/div>\\n\\t\\t<\\/div>\\n\\t<\\/div>\\n\\t<div style=\\\"max-width: 450px; margin: 10px auto; text-align: center;\\\">{{business_address}}<\\/div>\\n<\\/div>\"}}}],\"time_offset\":[]}]','active','2025-09-25 04:04:30','2025-09-25 04:04:30');
